class MyDataset(Dataset):
    def __init__(self, X, y):
        self.X = X
        self.y = y

    def __len__(self):
        return len(self.X)

    def __getitem__(self, idx):
        # Convert image from HWC numpy array to CHW float tensor
        x = self.X[idx]
        x = torch.tensor(x, dtype=torch.float32).permute(2, 0, 1) / 255.0

        # Build binary class label from paired watermark/non-watermark arrays
        # y entries are image arrays; use mean intensity heuristic to map to class id
        y_img = self.y[idx]
        label = 1 if np.mean(y_img) > 0 else 0
        y = torch.tensor(label, dtype=torch.long)

        return x, y

